  const nuit = "--gm-sea:#1C3340;--gm-land:#4E4433;--gm-coast:#7C6747;--gm-line:#F28A80;--gm-hl:#FFC233;--gm-foyer:#7CCB97;--gm-txt:#E8ECF5;--gm-halo:#141A26;--gm-ville:#E9C341";
