const ellipse = (e, cls) => { const [c, rx, ry, rot] = e, [x, y] = P(...c); return `<ellipse class="${cls}" cx="${x}" cy="${y}" rx="${rx}" ry="${ry}" transform="rotate(${rot} ${x} ${y})"/>`; };
const ligneY = (lat, y) => `M${P(-180, lat)[0] + 4},${y}H${P(180, lat)[0] - 4}`;
const parY = t => { // un parallèle s'arrête au bord de la carte
  const x0 = P(-180, t.lat)[0], x1 = P(180, t.lat)[0]; return `M${x0},${t.y}H${x1}`; };
const texte = (t, [x, y], cls = "") => `<text class="t ${cls}" x="${x}" y="${y + 4}">${esc(Maj(sansArt(nomCourt(t)).replace(" (foyer)", "")))}</text>`;

/* Dessine la carte. o : { lignes, noms (couches à nommer : "reperes", "monde", "population"), foyers,
   villes (true ou "num"), hl (nom d'un lieu à surligner), fleche } */
function carte(o = {}) {
  let s = `<svg class="gm" viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Planisphère"><path class="sea" d="${SPHERE}"/><path class="grat" d="${GRAT}"/><path class="land" d="${LAND}"/>`;
  if (o.lignes) DE("ligne").forEach(t => s += `<path class="par ${t.lat === 0 ? "eq" : ""}" d="${parY(t)}"/>`);
  if (o.foyers) { DE("foyer").forEach(t => s += ellipse(t.ell, "foy")); DE("secondaire").forEach(t => s += ellipse(t.ell, "sec")); }
  if (o.hl) s += surligne(L(o.hl));
  if (o.villes) DE("ville").forEach(t => { const [x, y] = t.px[0]; s += `<circle class="vil" cx="${x}" cy="${y}" r="${o.villes === "num" ? 5.5 : 4.5}"/>` + (o.villes === "num" ? `<text class="num" x="${x}" y="${y + 2.7}">${t.no}</text>` : ""); });
  const n = o.noms || [];
  if (n.includes("reperes")) {
    DE("ligne").forEach(t => s += `<text class="t par" x="${P(-36, t.lat)[0]}" y="${t.y - 4}">${esc(Maj(t.n.replace(/^l'|^le /, "")))}</text>`);
    s += `<text class="t big" x="400" y="20">Pôle Nord</text><text class="t big" x="400" y="404">Pôle Sud</text>`;
    DE("hemi").forEach(t => s += texte(t, t.lp, "it"));
  }
  if (n.includes("monde")) { DE("continent").forEach(t => s += texte(t, t.lp, "big")); DE("ocean").forEach(t => s += texte(t, t.lp, "it")); }
  if (n.includes("population")) {
    DE("region").forEach(t => s += texte(t, t.lp, "reg"));
    DE("foyer").forEach(t => s += texte(t, t.lp, "big"));
  }
  if (o.fleche) s += o.fleche;
  return s + `<g class="fx"></g></svg>`;
}
function surligne(t, pulse) {
  const c = pulse ? " pulse" : "";
  if (t.g === "ligne") return `<path class="hl${c}" d="${parY(t)}"/>`;
  if (t.g === "pole") return `<path class="hl${c}" d="${ligneY(t.lat, t.lat > 0 ? 8 : 408)}"/>`;
  if (t.g === "hemi") return `<rect class="hlz${c}" x="12" y="${t.nord ? 8 : CY}" width="776" height="200" rx="12"/>`;
  if (t.ell) return ellipse(t.ell, "hlz" + c);
  return t.px.map(([x, y]) => `<circle class="hlz${c}" cx="${x}" cy="${y}" r="${t.g === "ville" ? 14 : Math.max(20, t.r * .7)}"/>`).join("");
}
// Le lieu touché est-il le bon ? On cherche le lieu le plus proche du même genre.
function juge(nom, [x, y]) {
  const t = L(nom);
  if (t.g === "hemi") return t.nord ? y < CY - 3 : y > CY + 3;
  if (t.g === "pole") return t.lat > 0 ? y < 34 : y > H - 34;
  if (t.g === "ligne") { const best = DE("ligne").reduce((a, b) => Math.abs(b.y - y) < Math.abs(a.y - y) ? b : a); return best === t && Math.abs(t.y - y) < 16; }
  const d = u => Math.min(...u.px.map(([a, b]) => Math.hypot(a - x, b - y))) / (u.r || 18);
  const groupe = t.g === "foyer" ? DE("foyer") : DE(t.g);
  const best = groupe.reduce((a, b) => d(b) < d(a) ? b : a);
  const voisins = ["Paris", "Londres"]; // à 7 pixels l'un de l'autre : on accepte les deux
  const ok = best === t || (voisins.includes(t.n) && voisins.includes(best.n));
  return ok && d(t) < (t.g === "ville" ? 2.2 : 1.7);
}

