// d : écrite pour une élève de 6e, d'après des fiches recoupées (pas la leçon du professeur)
const DEFS = [
  { m: "un pôle", d: "Le point le plus au nord (le pôle Nord) ou le plus au sud (le pôle Sud) de la Terre. La Terre tourne sur elle-même autour d'un axe qui passe par les deux pôles.", ex: "Le pôle Nord est au milieu de l'océan Glacial Arctique.", r: ["pole", "un pole", "le pole", "les poles"] },
  { m: "l'équateur", d: "Une ligne imaginaire qui fait le tour de la Terre, à égale distance des deux pôles. Elle coupe la Terre en deux hémisphères.", ex: "L'équateur traverse l'Amazonie, le centre de l'Afrique et l'Indonésie.", r: ["equateur", "l equateur", "un equateur"] },
  { m: "un parallèle", d: "Un cercle imaginaire qui fait le tour de la Terre, parallèle à l'équateur. Plus on va vers les pôles, plus il est petit.", ex: "Les tropiques et les cercles polaires sont des parallèles.", r: ["parallele", "un parallele", "le parallele", "les paralleles"] },
  { m: "un hémisphère", d: "Une moitié de la Terre. L'équateur sépare l'hémisphère Nord et l'hémisphère Sud.", ex: "La France est dans l'hémisphère Nord, l'Australie dans l'hémisphère Sud.", r: ["hemisphere", "un hemisphere", "l hemisphere", "hemispheres"] },
  { m: "un foyer de population", d: "Une grande région où vivent un très grand nombre d'humains, souvent depuis très longtemps. La densité y est très forte.", ex: "L'Asie de l'Est, l'Asie du Sud et l'Europe.", r: ["foyer de population", "un foyer de population", "foyer", "un foyer", "foyer de peuplement", "un foyer de peuplement"] },
  { m: "la densité", d: "Le nombre moyen d'habitants par km². On la calcule en divisant le nombre d'habitants par la superficie.", ex: "1 000 habitants sur 10 km², cela fait 100 habitants par km².", r: ["densite", "la densite", "densite de population", "la densite de population"] },
  { m: "une contrainte naturelle", d: "Un élément de la nature qui gêne l'installation des humains : le froid, la sécheresse, la forêt dense, la haute montagne…", ex: "Le froid en Sibérie, la sécheresse au Sahara.", r: ["contrainte naturelle", "une contrainte naturelle", "contrainte", "une contrainte", "contraintes naturelles"] },
  { m: "une métropole", d: "Une très grande ville qui rassemble beaucoup d'habitants, d'activités et de services, et qui a de l'influence bien au-delà de ses limites.", ex: "Tokyo, Paris, New York.", r: ["metropole", "une metropole", "la metropole"] },
  { m: "une agglomération", d: "Une ville et toutes ses banlieues : elles forment un seul ensemble de constructions, sans coupure.", ex: "L'agglomération de Paris, c'est Paris et ses banlieues : 11,5 millions d'habitants.", r: ["agglomeration", "une agglomeration", "l agglomeration"] },
  { m: "l'exode rural", d: "Le départ des habitants des campagnes vers les villes, pour trouver du travail et une vie plus facile.", ex: "En Chine, beaucoup de paysans partent travailler dans les villes de la côte.", r: ["exode rural", "l exode rural", "un exode rural", "exode"] },
  { m: "les ruraux", d: "Les habitants des campagnes.", ex: "Un agriculteur qui vit dans un village est un rural.", r: ["ruraux", "les ruraux", "rural", "un rural"] },
  { m: "les urbains", d: "Les habitants des villes.", ex: "Plus de la moitié des humains sont aujourd'hui des urbains.", r: ["urbains", "les urbains", "urbain", "un urbain"] },
];
function definitions() {
  const x = one(DEFS);
  const motDef = () => q("Définitions", `Que veut dire <b>${esc(x.m)}</b> ?`, [x.d, ...autres(DEFS, x).map(y => y.d)], `Exemple : ${esc(x.ex)}`);
  const defMot = () => q("Définitions", `Quel mot correspond à cette définition ?<br><span style="font-weight:500;font-size:19px">« ${esc(x.d)} »</span>`, [Maj(x.m), ...autres(DEFS, x).map(y => Maj(y.m))], `Exemple : ${esc(x.ex)}`);
  const ecrire = () => Moteur.INPUT({ cat: "Définitions", prompt: `Écris le mot qui correspond :<br><span style="font-weight:500;font-size:19px">« ${esc(x.d)} »</span>`, fields: [{ mode: "text", w: "14em" }],
    check: ([v]) => x.r.includes(net(v)), answer: esc(Maj(x.m)), explain: ` Exemple : ${esc(x.ex)}` });
  return one([motDef, defMot, ecrire])();
}
definitions.liste = DEFS;

