const HEMI = [["Paris", "Nord"], ["São Paulo", "Sud"], ["Jakarta", "Sud"], ["Tokyo", "Nord"], ["Lagos", "Nord"], ["Mexico", "Nord"], ["l'Australie", "Sud"], ["l'Antarctique", "Sud"], ["le Groenland", "Nord"], ["le Sahara", "Nord"], ["l'Europe", "Nord"], ["la Sibérie", "Nord"], ["New York", "Nord"]];
function reperes() {
  return tirer([
    () => { const t = one(DE("ligne")); return q("Repères", "Comment s'appelle la ligne surlignée en orange ?", [Maj(t.n), ...autres(DE("ligne"), t).map(u => Maj(u.n))], "", { fig: carte({ lignes: true, hl: t.n }) }); },
    () => { const t = one([...DE("pole"), ...DE("hemi")]); return q("Repères", "Comment s'appelle ce qui est surligné en orange ?", [Maj(t.n), ...autres([...DE("pole"), ...DE("hemi")], t).map(u => Maj(u.n))], t.g === "hemi" ? "Un hémisphère, c'est la moitié de la Terre, de part et d'autre de l'équateur." : "Sur un planisphère, le pôle est tout le bord du haut (Nord) ou du bas (Sud).", { fig: carte({ lignes: true, hl: t.n }) }); },
    () => { const f = one(FAITS_LIGNES); return q("Repères", esc(f[0]), [f[1], ...f[2]], esc(f[3])); },
    () => { const [x, hm] = one(HEMI); return q("Repères", `Dans quel hémisphère se trouve <b>${esc(x)}</b> ?`, [`L'hémisphère ${hm}`, `L'hémisphère ${hm === "Nord" ? "Sud" : "Nord"}`], `${esc(Maj(x))} est ${hm === "Nord" ? "au nord" : "au sud"} de l'équateur.`, { keep: true }); },
  ]);
}

